	"gift_premium_terms_footer": "El precio de la suscripción de regalo se cobra en el momento de la compra y no es reembolsable. Es de un solo uso, no sustituible, no combinable y no tiene valor en efectivo. Comienza tras la revisión de X y la asignación al destinatario, que debe aceptar nuestros %1$s y nuestras políticas. Si el destinatario no cumple alguno de los requisitos de elegibilidad, cancela la suscripción o rechaza nuestros términos y políticas, el regalo no será canjeable ni reembolsable. Es posible que se apliquen impuestos. Los términos pueden cambiar. %2$s.",
