	"golive__tip_broadcaster_1": "<b>CONSEJO:</b> ¡Gracias por transmitir en directo! Saluda a las personas cuando se unan a tu video.",
	"golive__tip_broadcaster_10": "<b>CONSEJO:</b> ¡Gracias por transmitir en directo en X! ≺3",
	"golive__tip_broadcaster_2": "<b>CONSEJO:</b> Haz la prueba de llamar por su nombre a las personas que se unan a tu video en directo; ¡se emocionarán!",
	"golive__tip_broadcaster_3": "<b>CONSEJO:</b> Asegúrate de transmitir en directo por lo menos unos minutos para facilitar que las personas te encuentren.",
	"golive__tip_broadcaster_4": "<b>CONSEJO:</b> Pregunta a tus espectadores de dónde son; es una excelente manera de romper el hielo.",
	"golive__tip_broadcaster_5": "<b>CONSEJO:</b> Agradece a las personas por sintonizarte y responde a sus comentarios para que continúen viendo.",
	"golive__tip_broadcaster_6": "<b>CONSEJO:</b> Si pierdes tu conexión mientras transmites en directo, ve a otro lugar con mejor señal.",
	"golive__tip_broadcaster_7": "<b>CONSEJO:</b> Pide a las personas que te sigan para que reciban notificaciones la próxima vez que transmitas en directo.",
	"golive__tip_broadcaster_8": "<b>CONSEJO:</b> Comienza tu video en directo saludando enseguida. A las personas que estén viendo les encantará.",
	"golive__tip_broadcaster_9": "<b>CONSEJO:</b> Agradece a las personas por ver tu video en directo antes de que finalice.",
	"golive__tip_pre_broadcast_1": "<b>CONSEJO:</b> Escribe un título antes de transmitir en directo para ayudar a las personas a descubrir tu video.",
	"golive__tip_pre_broadcast_2": "<b>CONSEJO:</b> Un título descriptivo ayuda a las personas a entender de qué trata tu video en directo.",
	"golive__tip_pre_broadcast_3": "<b>CONSEJO:</b> ¿Necesitas ideas? Haz un recorrido, comparte un talento o habla sobre algo que te interese.",
	"golive__tip_pre_broadcast_4": "<b>CONSEJO:</b> Asegúrate de tener una señal de teléfono fuerte antes de transmitir en directo.",
	"golive__tip_pre_broadcast_5": "<b>CONSEJO:</b> Añade un hashtag a tu título para ayudar a las personas a descubrir tu video en directo.",
