	"identity_education_cancel": "Omitir por ahora",
	"identity_education_conditions": "Doy mi consentimiento para que X y Au10tix utilicen imágenes de mi identificación y mi selfie, incluidos los datos biométricos extraídos, para confirmar mi identidad y para fines de seguridad relacionados de X, incluida la prevención de la suplantación de identidad. Au10tix puede almacenar esos datos durante un máximo de 30 días. {{}}Más información{{}}",
	"identity_education_conditions_age_verification": "Acepto que X y Persona usen imágenes de mi documento de identidad y mi foto para confirmar mi edad. Tu foto no se almacenará. X y xAI pueden retener la información de tu edad. {{}}Obtener más información{{}}",
	"identity_education_conditions_eea": "\"Doy mi consentimiento para que X comparta imágenes de mi documento de identidad, incluyendo los datos biométricos, así como los datos personales de mi perfil con Au10tix con el propósito de confirmar mi identidad.\nDoy mi consentimiento para que X almacene las imágenes de mi documento de identidad, incluyendo los datos biométricos, durante un máximo de 30 días y para que use dichas imágenes, así como los datos de mi perfil, con el fin de ofrecer protección y seguridad, incluyendo la prevención de las instancias de suplantación de identidad. {{}}Más información{{}}\"",
	"identity_education_conditions_persona_vendor": "Acepto que X y Persona utilicen imágenes de mi DNI y de mi selfie, incluyendo los datos biométricos extraídos, para confirmar mi identidad y para fines relacionados con la seguridad, la prevención de fraudes y los pagos de X. Persona puede almacenar estos datos durante un máximo de 30 días. X puede almacenar el nombre completo, la dirección y los hashes de mi número de DNI mientras yo esté suscrito al servicio de X Premium. {{}}Más información{{}}",
