	"payment_funds_insurance_footer_secondary_text": "Obtén más información sobre el seguro de la FDIC y las categorías de propiedad de la cuenta ﻿aquí﻿.",
	"payment_funds_insurance_footer_text": "Cross River Bank, miembro de la FDIC, se encarga de retener los depósitos, y están asegurados por la FDIC por hasta USD 250.000 por persona física y jurídica para todas las cuentas en cada categoría de titularidad de cuenta mantenida en el banco (combinadas), incluidas las cuentas que se mantengan en calidad de representante.",
	"payment_funds_insurance_footer_text_format": "Cross River Bank (“el Banco”), miembro de la FDIC, se encarga de retener los depósitos, y están asegurados por la FDIC por hasta {amount} por persona física y jurídica para todas las cuentas en cada categoría de titularidad de cuenta mantenida en el Banco (combinadas), incluidas las cuentas que se mantengan en calidad de representante.",
	"payment_funds_insurance_sweep_disclaimer": "Los depósitos se mantienen en Cross River Bank, miembro de la FDIC, y en otras ﻿entidades aseguradas por la FDIC﻿. Para que se aplique la cobertura del seguro de depósitos por transferencia, deben cumplirse ﻿determinadas condiciones﻿. X Payments LLC no es un banco asegurado por la FDIC. El seguro de depósitos solo cubre la quiebra de un banco asegurado.",
	"payment_funds_insurance_sweep_presentation": "Tus depósitos se incluyen automáticamente en el programa Cash Sweep de X, que ofrece acceso a una cobertura total del seguro de la FDIC de hasta 10 millones de dólares, sujeta a ciertas limitaciones. ﻿Más información﻿.",
